import hashlib
import json
from pathlib import Path
from xml.etree import ElementTree
from zipfile import BadZipFile, ZipFile

from openpyxl import load_workbook


WORKBOOK = Path("02_Case_Review/Personal_Licence_Batch_Review_Register_2025-09.xlsx")
EXPECTED_STATES = {
    "Review Dashboard": "visible",
    "Application Review": "visible",
    "Discrepancy Log": "visible",
    "Source CSV Import": "visible",
    "Lists and Notes": "visible",
}
EXPECTED_NAMES = {
    "ApplicationStatuses": "'Lists and Notes'!$B$3:$B$4",
    "CheckStatuses": "'Lists and Notes'!$B$7:$B$9",
    "QualificationRoutes": "'Lists and Notes'!$B$12:$B$15",
    "RightToWorkMethods": "'Lists and Notes'!$B$18:$B$20",
    "DiscrepancyCategories": "'Lists and Notes'!$B$24:$B$29",
    "ResolutionStatuses": "'Lists and Notes'!$B$33:$B$36",
}
EXPECTED_VALIDATIONS = (
    ("Application Review", "list", "=CheckStatuses", None, "D7:E18"),
    ("Application Review", "list", "=QualificationRoutes", None, "F7:F18"),
    ("Application Review", "list", "=CheckStatuses", None, "G7:G18"),
    ("Application Review", "list", '"Complete,Action required,Not applicable"', None, "I7:I18"),
    ("Application Review", "list", "=RightToWorkMethods", None, "J7:J18"),
    ("Application Review", "list", "=CheckStatuses", None, "K7:K18"),
    ("Application Review", "list", '"Paid,Action required,Returned for clarification"', None, "M7:M18"),
    ("Application Review", "list", '"Not required,Drafted,Sent,Awaiting manager sign-off"', None, "R7:R18"),
    ("Discrepancy Log", "list", "=DiscrepancyCategories", None, "D7:D17"),
    ("Discrepancy Log", "list", "=ResolutionStatuses", None, "J7:J17"),
)
EXPECTED_CELL_HASHES = {
    "Review Dashboard": "90f23be797fc8b328a11499891a1c58a5718d6dabea3bd6fdcacffecdcd97b17",
    "Application Review": "d13f046f5147e44f424ddd47e403c772251222458f94c36c39b0272ebc15a32d",
    "Discrepancy Log": "5fbac913027c05e4223c35ec3d4f27dc2fe06714cbfaf34577298d33f8a97a2a",
    "Source CSV Import": "b7cf4898cefac8c844a18a801c50f81f868bd3f7ef9d2e6b1f408f09ede40953",
    "Lists and Notes": "20e65820b7a03d99b5a5e202035d35e642f781bfc9effca48ec1cc9243e4895d",
}


def _path(workspace):
    return Path(workspace) / WORKBOOK


def _cell_value(value):
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return str(value)


def _sheet_hash(ws):
    cells = []
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                cells.append([cell.coordinate, _cell_value(cell.value)])
    payload = json.dumps(cells, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _validation_signature(wb):
    found = []
    for ws in wb.worksheets:
        for validation in ws.data_validations.dataValidation:
            found.append((ws.title, validation.type, validation.formula1, validation.formula2, str(validation.sqref)))
    return tuple(found)


def check_target_sheet_visible(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "The review-register workbook is missing."}
    wb = load_workbook(path, data_only=False)
    actual = {ws.title: ws.sheet_state for ws in wb.worksheets}
    if actual != EXPECTED_STATES:
        return {"score": 0, "detail": f"Worksheet visibility mismatch: {actual}"}
    return {"score": 1, "detail": "Lists and Notes is visible and all other worksheets remain visible."}


def check_controls_preserved(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "The review-register workbook is missing."}
    wb = load_workbook(path, data_only=False)
    names = {name: definition.attr_text for name, definition in wb.defined_names.items()}
    if names != EXPECTED_NAMES:
        return {"score": 0, "detail": f"Defined-name mismatch: {names}"}
    actual_validations = _validation_signature(wb)
    if actual_validations != EXPECTED_VALIDATIONS:
        return {"score": 0, "detail": f"Validation definitions changed: {actual_validations}"}
    return {"score": 1, "detail": "Defined names and validation sources are unchanged."}


def check_workbook_contents_preserved(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "The review-register workbook is missing."}
    wb = load_workbook(path, data_only=False)
    actual = {ws.title: _sheet_hash(ws) for ws in wb.worksheets}
    if actual != EXPECTED_CELL_HASHES:
        changed = [name for name in EXPECTED_CELL_HASHES if actual.get(name) != EXPECTED_CELL_HASHES[name]]
        return {"score": 0, "detail": "Cell contents changed in: " + ", ".join(changed)}
    return {"score": 1, "detail": "Cell contents in all worksheets are unchanged."}


def check_workbook_design_preserved(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "The review-register workbook is missing."}
    try:
        with ZipFile(path) as archive:
            chart_xml = archive.read("xl/charts/chart1.xml")
    except (BadZipFile, KeyError):
        return {"score": 0, "detail": "The supplied Review Dashboard chart is missing or unreadable."}
    chart = ElementTree.fromstring(chart_xml)
    style = chart.find("{http://schemas.openxmlformats.org/drawingml/2006/chart}style")
    actual = None if style is None else style.get("val")
    if actual != "10":
        return {"score": 0, "detail": f"Review Dashboard chart style changed: expected 10, found {actual}."}
    return {"score": 1, "detail": "The supplied Review Dashboard chart style is preserved."}
